    int a, b, c;
    cin >> a >> b >> c;
    if (a >= b) {
        if (a >= c) {
            cout << "Largest = " << a << endl;
        } else {
            cout << "Largest = " << c << endl;
        }
    } else {
        if (b >= c) {
            cout << "Largest = " << b << endl;
        } else {
            cout << "Largest = " << c << endl;
        }
