What does this program print?

int a = 5, b = 0;
if (a > 0)
    if (b > 0) cout << "X";
else
    cout << "Y";

The programmer wants Y printed whenever a is not positive. Fix the code with braces.

int a = 5, b = 0;
if (a > 0)
    if (b > 0) cout << "X";
else cout << "Y";

practice.answer:
#include <iostream>
using namespace std;
int main() {
    int n;
    cin >> n;
    if (n > 0) {
        if (n % 2 == 0) {
            cout << "Positive even" << endl;
        } else {
            cout << "Positive odd" << endl;
        }
    } else {
        cout << "Not positive" << endl;
    }
    return 0;
}
